    H,W=len(I),len(I[0]); O=[r[:] for r in I]; seen=[[False]*W for _ in range(H)]
    comps=[]
    for i in range(H):
        for j in range(W):
            if I[i][j]!=0 and not seen[i][j]:
                col=I[i][j]; q=deque([(i,j)]); seen[i][j]=True; comp=[]
                while q:
                    x,y=q.popleft(); comp.append((x,y))
                    for dx,dy in ((1,0),(-1,0),(0,1),(0,-1)):
                        nx,ny=x+dx,y+dy
                        if 0<=nx<H and 0<=ny<W and I[nx][ny]==col and not seen[nx][ny]:
                            seen[nx][ny]=True; q.append((nx,ny))
                comps.append(comp)
    for comp in comps:
        rs=[p[0] for p in comp]; cs=[p[1] for p in comp]
        r0,r1,c0,c1=min(rs),max(rs),min(cs),max(cs)
        dist={p:max(abs(p[0]-a) for a in (r0,r1))+max(abs(p[1]-b) for b in (c0,c1)) for p in comp}
        # per-level color multiset
        levelcols={}
        for d in sorted(dist):
            cands=[I[p[0]][p[1]] for p in comp if dist[p]==d]
            levelcols[d]=[x for x in set(cands)]
        # outermost layer gets innermost's color, next gets previous layer's color... but each layer also has its own original color inside? check demo output colors
        rot=list(levelcols.values())[::-1]  # rotate order
        # instead use cyclic rotation of color list
        cols=list(levelcols.values())
        newcols=[cols[-1]]+[cols[k-1] for k in range(1,len(cols))]
        print('rot',newcols)
        for p,d in sorted(dist.items()):
            if d<len(newcols):
                O[p[0]][p[1]]=newcols[d%len(newcols)][0]
    return O
